ruleHooks.extraMethods:
; Colunas do período: 5 por mês (Estoque, Custo Op., Comodato, Faturamento, % Investimento)
; tabela(n) = tipo^largura^título
;
; set sc=$$ObterColunasMes^WDOMTESTECOM110RG(dataInicial,dataFinal,.tabela)
ObterColunasMes(dataInicial,dataFinal,tabela)	;
$$$VAR
new sc,tabMes,mes,edt,n
;
kill tabela
set sc=$$ObterMesesPeriodo(dataInicial,dataFinal,.tabMes)
if $$$ISERR(sc) quit sc
;
set (mes,n)=""
for  set mes=$order(tabMes(mes)) quit:mes=""  do
. set edt=$extract(tabMes(mes),5,6)_"/"_$extract(tabMes(mes),3,4)
. set n=n+1,tabela(n)="v2^11^Vlr Estoque "_edt
. set n=n+1,tabela(n)="v2^11^Custo Oper. "_edt
. set n=n+1,tabela(n)="v2^11^Vlr Comodato "_edt
. set n=n+1,tabela(n)="v2^11^Faturamento "_edt
. set n=n+1,tabela(n)="v2^9^% Invest. "_edt
;
quit $$$OK
;
; Meses do período: tabMes(n)=AAAAMM (até 12 meses)
;
; set sc=$$ObterMesesPeriodo^WDOMTESTECOM110RG(dataInicial,dataFinal,.tabMes)
ObterMesesPeriodo(dataInicial,dataFinal,tabMes)	;
$$$VAR
new anoMes,anoMesFinal,n
;
kill tabMes
if $get(dataInicial)=""!($get(dataFinal)="") quit $$$ERROR(10000,"Informe o período de faturamento!")
if dataFinal<dataInicial quit $$$ERROR(10000,"Data final menor que a data inicial!")
;
set anoMes=$$AnoMes(dataInicial),anoMesFinal=$$AnoMes(dataFinal),n=0
for  quit:anoMes>anoMesFinal  set n=n+1,tabMes(n)=anoMes,anoMes=$$ProximoMes(anoMes) quit:n>12
if n>12 quit $$$ERROR(10000,"Informe um período de no máximo 12 meses!")
;
quit $$$OK
;
; Ano/mês (AAAAMM) de uma data
;
; set anoMes=$$AnoMes^WDOMTESTECOM110RG(data)
AnoMes(data)	;
quit $zdate(data,8)\100
;
ProximoMes(anoMes)	;
quit $select(anoMes#100=12:(anoMes\100+1)*100+1,1:anoMes+1)
;
; Primeiro e último dia do mês (AAAAMM) em $horolog
;
PrimeiroDia(anoMes)	;
quit $zdateh(anoMes_"01",8)
;
UltimoDia(anoMes)	;
quit $zdateh($$ProximoMes(anoMes)_"01",8)-1
;
; Mês/Ano editado (MM/AAAA) de uma data
;
; set mesAno=$$MesAnoEditado^WDOMTESTECOM110RG(data)
MesAnoEditado(data)	;
quit $extract($zdate(data,8),5,6)_"/"_$extract($zdate(data,8),1,4)
;
; Carregar a consulta: uma linha por segmento/cliente com CCI no tipo de documento do segmento
; linha = segmento^cliente^valorCCI^codSegmento^codCliente^entidade^tipoMovimento^(5 valores por mês)
;
; set sc=$$CarregarGerenciador^WDOMTESTECOM110RG(term,codEmpresa,dataInicial,dataFinal,codCliente,codSegmento)
CarregarGerenciador(term,codEmpresa,dataInicial,dataFinal,codCliente,codSegmento)	;
$$$VAR
new sc,tabMes,segmento,tabEntidade,seq
;
kill ^||WDOMTESTECOMMASC
set sc=$$ObterMesesPeriodo(dataInicial,dataFinal,.tabMes)
if $$$ISERR(sc) quit sc
;
set sc=$$ObterEntidadesCliente(codEmpresa,$get(codCliente),.tabEntidade)
if $$$ISERR(sc) quit sc
;
set seq=0,segmento=""
if $get(codSegmento)'="" quit $$CarregarSegmento(term,codEmpresa,codSegmento,.tabMes,.tabEntidade,.seq)
for  set segmento=$order(^WDOMTESTECOMCFG(1,codEmpresa,1,segmento)) quit:segmento=""!$$$ISERR(sc)  do
. set sc=$$CarregarSegmento(term,codEmpresa,segmento,.tabMes,.tabEntidade,.seq)
;
quit sc
;
; Entidade do CCI de cada cliente (FTCL p27): tabEntidade(entidade)=cliente
;
; set sc=$$ObterEntidadesCliente^WDOMTESTECOM110RG(codEmpresa,codCliente,.tabEntidade)
ObterEntidadesCliente(codEmpresa,codCliente,tabEntidade)	;
$$$VAR
new sc,ftcl,cliente,entidade
;
kill tabEntidade
set sc=$$$OK
if $get(codCliente)'="" do  quit sc
. set sc=$$VerCliente^CCFTRG001(codEmpresa,codCliente,.ftcl)
. quit:$$$ISERR(sc)
. set entidade=$piece(ftcl,Z,27)
. if entidade'="" set tabEntidade(entidade)=codCliente
;
set cliente=""
for  set cliente=$order(^FTCL(codEmpresa,cliente)) quit:cliente=""  do
. set entidade=$piece($get(^FTCL(codEmpresa,cliente)),Z,27)
. if entidade'="",'$data(tabEntidade(entidade)) set tabEntidade(entidade)=cliente
;
quit $$$OK
;
; Carregar um segmento: valores por cliente e rateio do custo operacional pelo CCI
;
; set sc=$$CarregarSegmento^WDOMTESTECOM110RG(term,codEmpresa,codSegmento,.tabMes,.tabEntidade,.seq)
CarregarSegmento(term,codEmpresa,codSegmento,tabMes,tabEntidade,seq)	;
$$$VAR
new sc,cfg,tipoDocumento,tipoMovimento,cibtab,entidade,cliente,tabCliente,totalCCI,mes,despesa
new linha,valores,valorCCI,custo,comodato,faturamento,historico
;
set cfg=$get(^WDOMTESTECOMCFG(1,codEmpresa,1,codSegmento))
if cfg="" quit $$$ERROR(10000,"Segmento "_codSegmento_" não configurado!")
set tipoDocumento=$piece($get(^WDOMTESTECOMCFG(1,codEmpresa,1,codSegmento,1)),Z,3)
if tipoDocumento="" quit $$$OK
set sc=$$VerTipoDocto^CCCIBRG001(codEmpresa,tipoDocumento,.cibtab)
if $$$ISERR(sc) quit sc
set tipoMovimento=$piece(cibtab,Z,2)
;
; Valores por cliente (CCI, estoque e faturamento do mês)
kill tabCliente
set entidade="",totalCCI=0,sc=$$$OK
for  set entidade=$order(tabEntidade(entidade)) quit:entidade=""!$$$ISERR(sc)  do
. quit:'$data(^CIPDOC(codEmpresa,entidade,tipoMovimento,1))
. set cliente=tabEntidade(entidade)
. set sc=$$CalcularCliente(codEmpresa,codSegmento,tipoDocumento,tipoMovimento,entidade,cliente,.tabMes,.tabCliente)
. set totalCCI=totalCCI+$get(tabCliente(cliente))
if $$$ISERR(sc) quit sc
;
; Despesas operacionais do mês (conta x centro de custo) rateadas pelo CCI do cliente
set cliente="",sc=$$$OK
for  set cliente=$order(tabCliente(cliente)) quit:cliente=""!$$$ISERR(sc)  do
. set valorCCI=+$get(tabCliente(cliente)),valores="",mes=""
. for  set mes=$order(tabMes(mes)) quit:mes=""  do
. . set despesa=$$DespesaOperacional(codEmpresa,codSegmento,tabMes(mes))
. . set custo=$select(totalCCI:despesa*valorCCI/totalCCI,1:0)
. . set comodato=$get(tabCliente(cliente,mes,1))+custo
. . set faturamento=$get(tabCliente(cliente,mes,2))
. . set $piece(valores,Z,mes-1*5+1)=$$Valor($get(tabCliente(cliente,mes,1)))
. . set $piece(valores,Z,mes-1*5+2)=$$Valor(custo)
. . set $piece(valores,Z,mes-1*5+3)=$$Valor(comodato)
. . set $piece(valores,Z,mes-1*5+4)=$$Valor(faturamento)
. . set $piece(valores,Z,mes-1*5+5)=$$Valor($select(faturamento:comodato/faturamento*100,1:0))
. . ; Mês fechado: valores do histórico (item 3)
. . set historico=$get(^WDOMTESTECOMHIS(1,codEmpresa,tabMes(mes),codSegmento,cliente))
. . if historico'="" set $piece(valores,Z,mes-1*5+1,mes*5)=$piece(historico,Z,2,6)
. set linha=codSegmento_" - "_$piece(cfg,Z,3)_Z_cliente_" - "_$$NomeCliente(codEmpresa,cliente)_Z_$$Valor(valorCCI)
. set linha=linha_Z_codSegmento_Z_cliente_Z_$get(tabCliente(cliente,"E"))_Z_tipoMovimento_Z_valores
. set seq=seq+1
. set sc=$$GravarGlobalTrabalho(term,seq,linha)
;
quit sc
;
; Valor com 2 casas
;
Valor(valor)	;
quit +$justify(+$get(valor),0,2)
;
; Nome do cliente
;
; set nome=$$NomeCliente^WDOMTESTECOM110RG(codEmpresa,codCliente)
NomeCliente(codEmpresa,codCliente)	;
$$$VAR
new sc,ftcl
;
set sc=$$VerCliente^CCFTRG001(codEmpresa,codCliente,.ftcl)
;
quit $piece($get(ftcl),Z,2)
;
; Valores do cliente no segmento
; tabCliente(cliente) = valor do CCI em aberto hoje
; tabCliente(cliente,mes,1) = valor do estoque do CCI no fim do mês (saldo x preço médio)
; tabCliente(cliente,mes,2) = faturamento do mês (tipos de nota e máscaras acabado/revenda)
;
; set sc=$$CalcularCliente^WDOMTESTECOM110RG(codEmpresa,codSegmento,tipoDocumento,tipoMovimento,entidade,cliente,.tabMes,.tabCliente)
CalcularCliente(codEmpresa,codSegmento,tipoDocumento,tipoMovimento,entidade,cliente,tabMes,tabCliente)	;
$$$VAR
new sc,documento,produto,seqMov,dataMov,cibmov,qtd,valor,mes,ultimo,achou,anoMes
;
set (documento,achou)="",sc=$$$OK
for  set documento=$order(^CIPDOC(codEmpresa,entidade,tipoMovimento,1,documento)) quit:documento=""  do
. set produto=""
. for  set produto=$order(^CIPDOC(codEmpresa,entidade,tipoMovimento,1,documento,produto)) quit:produto=""  do
. . quit:'$$ItemDaMascara(codEmpresa,codSegmento,1,produto)
. . set seqMov=""
. . for  set seqMov=$order(^CIPDOC(codEmpresa,entidade,tipoMovimento,1,documento,produto,seqMov)) quit:seqMov=""  do
. . . set dataMov=+$piece(documento,";",2)
. . . set cibmov=$get(^CIBMOV(codEmpresa,dataMov,seqMov))
. . . quit:$piece(cibmov,Z,1)'=tipoDocumento
. . . set achou=1
. . . set sc=$$ObterSaldoMovimentoCCI^CCCIBRG002(codEmpresa,dataMov,seqMov,+$h,.qtd,.valor)
. . . set tabCliente(cliente)=$get(tabCliente(cliente))+(valor/100)
. . . set mes=""
. . . for  set mes=$order(tabMes(mes)) quit:mes=""  do
. . . . set anoMes=tabMes(mes),ultimo=$$UltimoDia(anoMes)
. . . . quit:dataMov>ultimo
. . . . set sc=$$ObterSaldoMovimentoCCI^CCCIBRG002(codEmpresa,dataMov,seqMov,ultimo,.qtd,.valor)
. . . . set tabCliente(cliente,mes,1)=$get(tabCliente(cliente,mes,1))+((qtd/1000)*$$ObterPrecoMedioEst^CCESA202RG(codEmpresa,produto,anoMes,"","","",1))
if achou="" quit $$$OK
;
set tabCliente(cliente,"E")=entidade
set mes=""
for  set mes=$order(tabMes(mes)) quit:mes=""  set tabCliente(cliente,mes,2)=$$FaturamentoMes(codEmpresa,codSegmento,cliente,tabMes(mes))
;
quit $$$OK
;
; Item pertence às máscaras do segmento (lista 1 = itens enviados, 3 = acabado/revenda; sem máscara = todos)
; As máscaras de cada lista são expandidas uma vez por consulta em ^||WDOMTESTECOMMASC.
;
; if $$ItemDaMascara^WDOMTESTECOM110RG(codEmpresa,codSegmento,lista,codItem)
ItemDaMascara(codEmpresa,codSegmento,lista,codItem)	;
$$$VAR
new sc,mascara,item,qtd,chave,id
;
if '$data(^WDOMTESTECOMCFG(1,codEmpresa,1,codSegmento,1,lista)) quit 1
if '$data(^||WDOMTESTECOMMASC(codSegmento,lista)) do
. set ^||WDOMTESTECOMMASC(codSegmento,lista)="",mascara="",id="WDCOM"_lista
. for  set mascara=$order(^WDOMTESTECOMCFG(1,codEmpresa,1,codSegmento,1,lista,mascara)) quit:mascara=""  do
. . set sc=$$ObterTabelaMascaras^CCCGIRG012(codEmpresa,mascara,"S","",.qtd,id)
. . set chave=""
. . for  set chave=$order(^mtempSelMasc($job,id,chave)) quit:chave=""  set ^||WDOMTESTECOMMASC(codSegmento,lista,chave)=""
. . set sc=$$ExcluirTabelaMascara^CCCGIRG012(id)
;
set item=$piece($get(^CGISAI(codEmpresa,codItem)),Z,1)
if item="" quit 0
;
quit $data(^||WDOMTESTECOMMASC(codSegmento,lista,"X"_item))>0
;
; Despesas operacionais do mês: débitos das contas x centros de custo do segmento (^CTSCCC)
;
; set valor=$$DespesaOperacional^WDOMTESTECOM110RG(codEmpresa,codSegmento,anoMes)
DespesaOperacional(codEmpresa,codSegmento,anoMes)	;
$$$VAR
new conta,centro,data,total
;
set data=$$PrimeiroDia(anoMes),conta="",total=0
for  set conta=$order(^WDOMTESTECOMCFG(1,codEmpresa,1,codSegmento,2,1,conta)) quit:conta=""  do
. set centro=""
. for  set centro=$order(^WDOMTESTECOMCFG(1,codEmpresa,1,codSegmento,2,2,centro)) quit:centro=""  do
. . set total=total+($piece($get(^CTSCCC(codEmpresa,1,conta,centro,data)),Z,2)/100)
;
quit total
;
; Faturamento do cliente no mês (soma do valor bruto dos itens faturados do segmento)
;
; set valor=$$FaturamentoMes^WDOMTESTECOM110RG(codEmpresa,codSegmento,codCliente,anoMes)
FaturamentoMes(codEmpresa,codSegmento,codCliente,anoMes)	;
$$$VAR
new sc,tabNota,n,total
;
set sc=$$ObterItensFaturados(codEmpresa,codSegmento,codCliente,anoMes,.tabNota)
set n="",total=0
for  set n=$order(tabNota(n)) quit:n=""  set total=total+$piece(tabNota(n),Z,6)
;
quit total
;
; Itens faturados do cliente no mês (^FTFC): notas dos tipos do segmento, itens das máscaras acabado/revenda
; tabNota(n) = data^nota^item^produto^quantidade^bruto^impostos^unitário
;
; set sc=$$ObterItensFaturados^WDOMTESTECOM110RG(codEmpresa,codSegmento,codCliente,anoMes,.tabNota)
ObterItensFaturados(codEmpresa,codSegmento,codCliente,anoMes,tabNota)	;
$$$VAR
new data,ultimo,nota,item,ftnf,ftnfi,n,impostos
;
kill tabNota
set data=$$PrimeiroDia(anoMes)-1,ultimo=$$UltimoDia(anoMes),n=0
for  set data=$order(^FTFC(codEmpresa,codCliente,data)) quit:data=""!(data>ultimo)  do
. set nota=""
. for  set nota=$order(^FTFC(codEmpresa,codCliente,data,nota)) quit:nota=""  do
. . set ftnf=$get(^FTNF(codEmpresa,data,nota))
. . if $data(^WDOMTESTECOMCFG(1,codEmpresa,1,codSegmento,1,2)),'$data(^WDOMTESTECOMCFG(1,codEmpresa,1,codSegmento,1,2,+$piece(ftnf,Z,1))) quit
. . set item=""
. . for  set item=$order(^FTNF(codEmpresa,data,nota,item)) quit:item=""  do
. . . quit:item'=+item
. . . set ftnfi=$get(^FTNF(codEmpresa,data,nota,item))
. . . quit:'$$ItemDaMascara(codEmpresa,codSegmento,3,$piece(ftnfi,Z,1))
. . . ; Impostos: IPI (5) + ICMS (12) + ICMS ST (14) + PIS (73) + COFINS (74), valores x100
. . . set impostos=($piece(ftnfi,Z,5)+$piece(ftnfi,Z,12)+$piece(ftnfi,Z,14)+$piece(ftnfi,Z,73)+$piece(ftnfi,Z,74))/100
. . . set n=n+1,tabNota(n)=data_Z_nota_Z_item_Z_$piece(ftnfi,Z,1)_Z_($piece(ftnfi,Z,2)/1000)_Z_($piece(ftnfi,Z,4)/100)_Z_impostos_Z_($piece(ftnfi,Z,3)/100)
;
quit $$$OK
;
; Histórico do mês (item 3, agendador no fechamento)
; ^WDOMTESTECOMHIS(1,emp,anoMes,segmento,cliente) = valorCCI^estoque^custo^comodato^faturamento^%investimento
;
; set sc=$$GravarHistoricoMes^WDOMTESTECOM110RG(codEmpresa,anoMes)
GravarHistoricoMes(codEmpresa,anoMes)	;
$$$VAR
new sc,term,seq,linha
;
set term="HIS"_$job
kill ^mtempWDOMTESTECOM110(term)
set sc=$$CarregarGerenciador(term,codEmpresa,$$PrimeiroDia(anoMes),$$UltimoDia(anoMes),"","")
if $$$ISERR(sc) kill ^mtempWDOMTESTECOM110(term) quit sc
;
set seq=""
for  set seq=$order(^mtempWDOMTESTECOM110(term,seq)) quit:seq=""  do
. set linha=^mtempWDOMTESTECOM110(term,seq)
. do $$$SetG(^WDOMTESTECOMHIS(1,codEmpresa,anoMes,$piece(linha,Z,4),$piece(linha,Z,5)),$piece(linha,Z,3)_Z_$piece(linha,Z,8,12))
kill ^mtempWDOMTESTECOM110(term)
;
quit $$$OK
;
; Entrada do agendador de tarefas: grava o histórico do mês anterior
;
; do AgendadorHistorico^WDOMTESTECOM110RG(codEmpresa)
AgendadorHistorico(codEmpresa)	;
$$$VAR
new sc,anoMes
;
set anoMes=$$AnoMes(+$h)
set anoMes=$select(anoMes#100=1:(anoMes\100-1)*100+12,1:anoMes-1)
set sc=$$GravarHistoricoMes(codEmpresa,anoMes)
;
quit
